  if(quotesOnly){
   state.result={mode:'market',query:state.query,documentQuery:'',scope:tickers,summary:'Market quotes only. No company documents or model synthesis were used.',findings:[],evidence:[],gaps:[],trace:[{tool:'route_request',detail:'Price-only request: market data only; company documents and model synthesis skipped.',ms:0},{tool:'fetch_quotes',detail:'Quotes requested from the market-data provider for '+tickers.join(', ')+'.',ms:0}],generatedAt:new Date().toISOString(),marketRequested:true,token};
   setView('research');scrollToWork();await loadMarket(tickers,token);return state.result;
  }
