  const writes=[['finn-prefs',n.prefs],['finn-display',n.display],['finn-terminal-extra',n.terminalExtra],['finn-terminal-source',n.terminalSource]].map(([key,value])=>({key,value:JSON.stringify(value),old:localStorage.getItem(key)}));
  try{for(const w of writes)localStorage.setItem(w.key,w.value)}catch{for(const w of writes){try{w.old===null?localStorage.removeItem(w.key):localStorage.setItem(w.key,w.old)}catch{}}throw new Error('The workspace could not save the changes. Device storage may be full.')}
