 function showImport(ticker=state.ticker){openModal('Add document',`<p class="notebook-subtitle">A text-based company PDF becomes searchable evidence. No model key required.</p><form id="import-form"><div class="field"><label for="upload-file">ORIGINAL PDF</label><input id="upload-file" name="file" type="file" accept="application/pdf,.pdf" required><small>Up to 15 MB and 350 pages. Scanned documents need OCR first.</small></div><div class="field-row"><div class="field"><label for="upload-ticker">NSE TICKER</label><input id="upload-ticker" name="ticker" value="${escape(ticker)}" maxlength="24" required placeholder="e.g. INFY"></div><div class="field"><label for="upload-type">DOCUMENT TYPE</label><select id="upload-type" name="type"><option value="transcript">Earnings-call transcript</option><option value="annual_report">Annual report</option></select></div></div><div class="field-row"><div class="field"><label for="upload-period">REPORTING PERIOD</label><input id="upload-period" name="period" placeholder="e.g. Q2 FY27" maxlength="50" required></div><div class="field"><label for="upload-date">DOCUMENT DATE</label><input id="upload-date" name="date" type="date" required></div></div><p class="check-note">The PDF is sent to this app’s server for parsing. Its extracted text is saved on this device. Source authenticity is your responsibility.</p><button class="solid-button" type="submit" id="import-submit">Extract & add to library ↗</button><div id="import-status" role="status"></div></form>`)}
