 function bookmark(id){const b=state.briefs.find(b=>b.id===id);if(!b)return;const existing=state.saved.some(s=>s.id===id);const next=existing?state.saved.filter(s=>s.id!==id):[{id,kind:'signal',ticker:b.ticker,title:b.headline,description:b.deck},...state.saved];if(persist('finn-saved',next)){state.saved=next;render();toast(existing?'Bookmark removed.':'Signal saved on this device.')}}
 function saveResearch(){const r=currentResult();if(!r)return;const id='research-'+Date.now();const market=marketSnapshot(r),next=[{id,kind:r.mode==='market'?'market':'research',ticker:r.scope?.[0]||r.reviewContext?.ticker||state.ticker,title:r.query,description:r.summary,result:{...r,...(market?{market}:{})}},...state.saved].slice(0,30);if(persist('finn-saved',next)){state.saved=next;toast(r.mode==='market'?'Market snapshot saved with its provider timestamps.':'Research note saved on this device.')}}
 function exportResearch(){const r=currentResult();if(!r)return;const market=marketSnapshot(r);const text=`# ${r.query}\n\nCompany: ${(r.scope?.join(' × ')||r.reviewContext?.ticker||state.ticker)}\nMode: ${r.mode}\nGenerated: ${r.generatedAt||new Date().toISOString()}\n${r.documentQuery&&r.documentQuery!==r.query?'Question sent to company documents: '+r.documentQuery+'\n':''}\n${r.summary}\n\n${market?marketMarkdown(market):''}${r.findings.length?'## Findings\n\n'+findingsMarkdown(r)+'\n\n':''}${r.evidence.length?'## Evidence\n\n'+r.evidence.map((e,i)=>`### [${i+1}] ${e.document?.title||'Company document'} — page ${e.page}\n\n${e.text}\n\n${e.document?.url?sourceURL(e):'Uploaded on this device'}`).join('\n\n')+'\n\n':''}${r.gaps?.length?'## Gaps\n\n'+r.gaps.map(g=>'- '+g).join('\n')+'\n':''}`;const link=document.createElement('a');const blobURL=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));link.href=blobURL;link.download='FINN-'+(r.scope?.join('-')||r.reviewContext?.ticker||state.ticker)+(r.mode==='market'?'-market-snapshot.md':'-research.md');link.click();setTimeout(()=>URL.revokeObjectURL(blobURL),1000)}
